<?php
require_once __DIR__ . '/../database/app/layout.php';
$u=current_user(); $pdo=db();
$term=trim($_GET['q']??''); $area=trim($_GET['area']??'');
$sql="SELECT sf.*,u.name AS donor_name,u.address AS donor_address FROM surplus_food sf JOIN users u ON u.id=sf.restaurant_id WHERE sf.status='available' AND sf.safety_deadline>NOW() AND EXISTS (SELECT 1 FROM food_safety_checks fsc WHERE fsc.surplus_food_id=sf.id AND fsc.result='safe')";
$args=[];
if($term!==''){ $sql.=" AND (sf.food_name LIKE ? OR sf.description LIKE ? OR sf.category LIKE ?)"; $args[]="%$term%";$args[]="%$term%";$args[]="%$term%"; }
if($area!==''){ $sql.=" AND (u.address LIKE ? OR sf.pickup_address LIKE ?)";$args[]="%$area%";$args[]="%$area%"; }
$sql.=" ORDER BY (sf.priority_score + CASE WHEN TIMESTAMPDIFF(HOUR,NOW(),sf.safety_deadline) <= 3 THEN 35 WHEN TIMESTAMPDIFF(HOUR,NOW(),sf.safety_deadline) <= 8 THEN 20 WHEN TIMESTAMPDIFF(HOUR,NOW(),sf.safety_deadline) <= 24 THEN 10 ELSE 0 END) DESC, sf.safety_deadline ASC LIMIT 100";
$stmt=$pdo->prepare($sql);$stmt->execute($args);$foods=$stmt->fetchAll();
page_header('Available surplus food');
?>
<div class="page-intro"><div class="eyebrow">SAFE SURPLUS, REAL IMPACT</div><h1>Available food <em>near you.</em></h1><p>Browse current listings. Food is shown only while its safety deadline has not passed.</p></div>
<div class="section" style="padding-top:0"><a class="btn btn-light" href="<?= e(url('area_map.php')) ?>">View area-wise map ↗</a> <?php if($u && in_array($u['role'],['ngo','demand_reporter'],true)): ?><a class="btn btn-light" href="<?= e(url('matches.php')) ?>">Smart matches ↗</a><?php endif; ?></div><form class="filter-bar" method="get"><input name="q" value="<?= e($term) ?>" placeholder="Search food, category..."><input name="area" value="<?= e($area) ?>" placeholder="Area / district"><button class="btn" type="submit">Search</button></form>
<?php if(!$foods): ?><div class="empty-state"><div>🥗</div><h3>No active food listings found</h3><p>Try another food name or area. Listings appear here only when their safety deadline is in the future and a safety check is marked safe. For local demo data, run php scripts/seed_demo.php from the project root in a development environment.</p>
<?php if (in_array(strtolower((string)($_SERVER['HTTP_HOST'] ?? '')), ['localhost','localhost:80','127.0.0.1','127.0.0.1:80'], true)): ?><div class="alert warning" style="text-align:left;max-width:720px;margin:18px auto"><strong>Local demo data not showing?</strong><br>Run the local demo setup page once, then refresh this page. It adds sample food listings and safety-review records.<br><a class="btn btn-sm" style="margin-top:12px" href="<?= e(url('setup_demo.php')) ?>">Set up demo data</a><br><small>Demo listings are illustrative, not real donations.</small></div><?php endif; ?></div><?php else: ?><div class="food-grid">
<?php foreach($foods as $f): ?><article class="food-card"><div class="food-card-art"><span class="food-category"><?= e($f['category']) ?></span><span class="priority">Priority <?= (int)$f['priority_score'] ?>/100</span><img class="food-photo" loading="lazy" src="<?= e(food_image_url($f)) ?>" alt="<?= e($f['food_name']) ?>"></div><div class="food-card-body"><div class="food-title-row"><h3><?= e($f['food_name']) ?></h3><?= status_badge($f['status']) ?></div><p><?= e($f['description']) ?></p><div class="food-meta"><span>⚖ <?= e((string)$f['quantity_kg']) ?> kg</span><span>⌖ <?= e($f['pickup_address'] ?: $f['donor_address']) ?></span></div><div class="deadline">Safe pickup deadline <b><?= e(date('d M, g:i A',strtotime($f['safety_deadline']))) ?></b><small data-deadline="<?= e(date('c',strtotime($f['safety_deadline']))) ?>">Countdown loading…</small></div><div class="food-card-footer"><small>Donated by <?= e($f['donor_name']) ?><?php if(($f['source_type']??'')==='event_leftover'): ?> · <strong>Event donation</strong><?php endif; ?></small><?php if($u && in_array($u['role'],['ngo','demand_reporter'],true)): ?><form method="post" action="<?= e(url('request_donation.php')) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="food_id" value="<?= (int)$f['id'] ?>"><button class="btn btn-sm" type="submit">Request food ↗</button></form><?php elseif(!$u): ?><a class="btn btn-sm" href="<?= e(url('login.php')) ?>">Log in to request</a><?php endif; ?></div></div></article><?php endforeach; ?>
</div><?php endif; ?>
<script>document.querySelectorAll('[data-deadline]').forEach(function(el){function tick(){var ms=new Date(el.dataset.deadline).getTime()-Date.now();if(ms<=0){el.textContent='Expired — unavailable';return;}var h=Math.floor(ms/3600000),m=Math.floor((ms%3600000)/60000);el.textContent='Time left: '+h+'h '+m+'m';}tick();setInterval(tick,60000);});</script>
<?php page_footer(); ?>
